      "pattern": "[aller (imparfait)] + [infinitif]",
      "examples": [
        {
          "origin": "ai",
          "situation": "同事詢問某人為何還在辦公室，對方說明正要離開時突然有訪客。",
          "dialogue": [
            {
              "text": "Tu es encore au bureau ?",
              "translation": "你還在辦公室嗎？"
            },
            {
              "text": "J'allais partir quand un client est arrivé.",
              "translation": "當一位客戶抵達時，我正打算離開。"
            }
          ],
          "targetLineIndex": 1,
